**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int odwroc(int n) {
    int odw = 0;
    while (n > 0) {
        odw = odw * 10 + n % 10;
        n /= 10;
    }
    return odw;
}

bool czyPierwsza(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2)
        if (n % i == 0) return false;
    return true;
}

int main() {
    ifstream plik("dane.txt");
    int liczba;
    vector<int> liczby, odwrocenia;
    while (plik >> liczba) {
        liczby.push_back(liczba);
        odwrocenia.push_back(odwroc(liczba));
    }

    cout << "a) Odwrocenia i palindromy:" << endl;
    int palindromy = 0;
    for (int i = 0; i < (int)liczby.size(); i++) {
        bool pal = (liczby[i] == odwrocenia[i]);
        cout << liczby[i] << " -> odw: " << odwrocenia[i]
             << ", palindrom: " << (pal ? "TAK" : "NIE") << endl;
        if (pal) palindromy++;
    }
    cout << "Palindromow: " << palindromy << endl;

    cout << endl << "b) Liczby z pierwszym odwroceniem:" << endl;
    int ile = 0;
    for (int i = 0; i < (int)liczby.size(); i++) {
        if (czyPierwsza(odwrocenia[i])) {
            cout << liczby[i] << " (odw: " << odwrocenia[i] << ")" << endl;
            ile++;
        }
    }
    cout << "Ilosc: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Odwracanie przez `odw = odw * 10 + n % 10` buduje liczbe z cyfr od konca. Palindrom to `liczba == odwrocona`. Test pierwszosci standardowy z optymalizacja `i * i <= n`.

